  -- (2) Observe every candidate not yet observed.
  observed AS (
    INSERT INTO public.first_hop_enqueue_retries (strategy_id)
    SELECT c.id
      FROM cand c
     WHERE NOT EXISTS (
             SELECT 1 FROM public.first_hop_enqueue_retries r0 WHERE r0.strategy_id = c.id
