     WHERE r.reenqueued_at IS NOT NULL
       AND r.named_state_at IS NULL
       AND EXISTS (
             SELECT 1
               FROM public.compute_jobs cjf
              WHERE cjf.strategy_id = r.strategy_id
                AND cjf.status = 'failed_final'
