       AND NOT EXISTS (
             SELECT 1
               FROM public.compute_jobs cjn
              WHERE cjn.strategy_id = r.strategy_id
                AND cjn.status <> 'failed_final'
           )
       AND NOT EXISTS (
             SELECT 1
               FROM public.strategy_analytics san
              WHERE san.strategy_id = r.strategy_id
